The conditional block barrier violates the synchronization contract: `__syncthreads()` in conditional code requires a condition uniform across the block. With `valid = 70`, threads 70–95 skip the load and barrier while threads 0–69 enter them. This is invalid synchronization, not a guarantee that every device hangs; successful immediate launch checks do not establish runtime correctness.

Move the barrier outside the conditional. This complete example launches one block of 96 threads for every valid count, including zero.

```cpp
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

#define CHECK(call) do {                                      \
    cudaError_t error = (call);                               \
    if (error != cudaSuccess) {                              \
        std::fprintf(stderr, "%s: %s\n", #call,              \
                     cudaGetErrorString(error));             \
        std::exit(EXIT_FAILURE);                             \
    }                                                        \
} while (false)

__global__ void sum_valid(const float* input, float* output, int valid)
{
    __shared__ float values[96];
    const int tid = static_cast<int>(threadIdx.x);

    if (tid < valid) {
        values[tid] = input[tid];
    }

    __syncthreads();

    if (tid == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i) {
            sum += values[i];
        }
        output[0] = sum;
    }
}

// input: at least valid device floats; may be null for valid == 0.
// output: at least one writable device float.
// Allocations must remain valid until completion, with no conflicting access.
cudaError_t launch_sum(const float* input, float* output,
                       int valid, cudaStream_t stream)
{
    if (valid < 0 || valid > 96 || output == nullptr ||
        (valid > 0 && input == nullptr)) {
        return cudaErrorInvalidValue;
    }
    sum_valid<<<1, 96, 0, stream>>>(input, output, valid);
    return cudaGetLastError();
}

int main()
{
    float input[96];
    for (float& value : input) value = 1.0f;

    float* device_input = nullptr;
    float* device_output = nullptr;
    cudaStream_t stream;
    CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_input),
                     sizeof(input)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_output),
                     sizeof(float)));
    CHECK(cudaMemcpy(device_input, input, sizeof(input),
                     cudaMemcpyHostToDevice));

    for (int valid = 0; valid <= 96; ++valid) {
        CHECK(launch_sum(valid == 0 ? nullptr : device_input,
                         device_output, valid, stream));
        CHECK(cudaStreamSynchronize(stream));
        float result;
        CHECK(cudaMemcpy(&result, device_output, sizeof(result),
                         cudaMemcpyDeviceToHost));
        if (result != static_cast<float>(valid)) {
            std::fprintf(stderr, "Incorrect result for valid=%d\n", valid);
            return EXIT_FAILURE;
        }
    }

    CHECK(cudaFree(device_output));
    CHECK(cudaFree(device_input));
    CHECK(cudaStreamDestroy(stream));
    std::puts("All valid counts passed.");
    return EXIT_SUCCESS;
}
```

