Only negative cycles reachable from s and able to reach t make the answer unbounded. This implementation uses deterministic Bellman–Ford passes and exact Python integers.

```python
def classify_root(N, edges, s, t):
    edges = list(edges)
    forward = [[] for _ in range(N)]
    reverse = [[] for _ in range(N)]
    for u, v, w in edges:
        forward[u].append(v)
        reverse[v].append(u)

    def reachable(start, graph):
        seen = [False] * N
        seen[start] = True
        stack = [start]
        while stack:
            u = stack.pop()
            for v in graph[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
        return seen

    from_s = reachable(s, forward)
    if not from_s[t]:
        return ('unreachable', None)
    to_t = reachable(t, reverse)

    relevant = [from_s[v] and to_t[v] for v in range(N)]
    K = sum(relevant)
    query_edges = [
        (u, v, w) for u, v, w in edges
        if relevant[u] and relevant[v]
    ]

    dist = [None] * N
    dist[s] = 0
    for _ in range(K - 1):
        next_dist = dist.copy()
        changed = False
        for u, v, w in query_edges:
            if dist[u] is None:
                continue
            candidate = dist[u] + w
            if next_dist[v] is None or candidate < next_dist[v]:
                next_dist[v] = candidate
                changed = True
        dist = next_dist
        if not changed:
            break

    for u, v, w in query_edges:
        if dist[u] is None:
            continue
        candidate = dist[u] + w
        if dist[v] is None or candidate < dist[v]:
            return ('unbounded', None)

    return ('finite', dist[t])
```

