The conditional barrier violates the block synchronization contract: with valid = 70, threads 0–69 reach `__syncthreads()`, while threads 70–95 skip it. This is invalid synchronization, not a guarantee that every device hangs. Immediate launch checks do not establish successful asynchronous execution or synchronization correctness.

Move the barrier outside the conditional. Compile this complete example with `nvcc -std=c++17 sum.cu -o sum` and run `./sum`.

```cpp
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

#define CHECK(call) do { \
    cudaError_t error = (call); \
    if (error != cudaSuccess) { \
        std::fprintf(stderr, "%s: %s\n", #call, \
                     cudaGetErrorString(error)); \
        std::exit(EXIT_FAILURE); \
    } \
} while (false)

__global__ void sum_valid(const float* input, float* output, int valid)
{
    __shared__ float values[96];
    const int tid = static_cast<int>(threadIdx.x);

    if (tid < valid) {
        values[tid] = input[tid];
    }

    __syncthreads();

    if (tid == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i) {
            sum += values[i];
        }
        output[0] = sum;
    }
}

// input contains at least valid device floats; null is allowed for zero.
// output contains at least one writable device float.
// Allocations remain valid until completion, without conflicting accesses.
cudaError_t launch_sum(const float* input, float* output,
                       int valid, cudaStream_t stream)
{
    if (valid < 0 || valid > 96 || output == nullptr ||
        (valid > 0 && input == nullptr)) {
        return cudaErrorInvalidValue;
    }
    sum_valid<<<1, 96, 0, stream>>>(input, output, valid);
    return cudaGetLastError();
}

int main()
{
    float input[96];
    for (float& value : input) value = 1.0f;

    float* device_input = nullptr;
    float* device_output = nullptr;
    cudaStream_t stream;
    CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_input),
                     sizeof(input)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_output),
                     sizeof(float)));
    CHECK(cudaMemcpy(device_input, input, sizeof(input),
                     cudaMemcpyHostToDevice));

    for (int valid = 0; valid <= 96; ++valid) {
        CHECK(launch_sum(valid == 0 ? nullptr : device_input,
                         device_output, valid, stream));
        CHECK(cudaStreamSynchronize(stream));
        float result;
        CHECK(cudaMemcpy(&result, device_output, sizeof(result),
                         cudaMemcpyDeviceToHost));
        if (result != static_cast<float>(valid)) {
            std::fprintf(stderr, "Incorrect result for valid=%d\n", valid);
            return EXIT_FAILURE;
        }
    }

    CHECK(cudaFree(device_output));
    CHECK(cudaFree(device_input));
    CHECK(cudaStreamDestroy(stream));
    std::puts("All valid counts passed.");
    return EXIT_SUCCESS;
}
```

For every accepted valid count, all 96 threads reach the same unconditional barrier. Every shared-memory index `i` read by thread zero satisfies `0 <= i < valid <= 96`; thread `i` therefore initializes `values[i]` before the barrier, which makes that write visible before the read. No input index at or above `valid` is read, and unused shared entries are never read.

When `valid = 0`, the kernel still launches all 96 threads and executes the barrier. Thread zero performs no additions and writes `output[0] = 0.0f`; no host initialization is needed. For other counts, it adds inputs in ascending index order with ordinary float rounding.

In the original kernel with `valid = 70`, threads 70–95 fail `tid < valid`, so they skip the input read, shared-memory write, and conditional barrier; they do not write the output. Threads 0–69 enter the barrier under a nonuniform block condition, violating the synchronization contract. This is invalid synchronization—not a guarantee that every device hangs. Immediate launch checks detect launch errors, not successful asynchronous completion or correct synchronization; even successful completion does not prove correctness.

